<template><div class="page fade-up"><router-link :to="`/projects/${pid}`" class="back">← 返回项目</router-link><div class="head"><div><h1>角色造型资产</h1><p class="sub">服装、鞋履、发型、发饰、首饰和包独立审核，并按场景选择。</p></div><button class="btn" @click="open()">＋ 新建造型</button></div><div v-if="error" class="notice error-notice">{{error}}</div><div class="look-grid"><article v-for="x in looks" :key="x.id" class="card look"><img v-if="x.image" :src="`/api/input/${pid}/${x.image}`"><div v-else class="empty-img">暂无参考图</div><header><h3>{{x.name}}</h3><span class="badge">{{labels[x.category]}}</span></header><p>{{x.description||'暂无描述'}}</p><small>{{x.audit_status}} · 优先级 {{x.priority}} <b v-if="x.is_shot_related">· H3镜头相关</b></small><div class="actions"><button class="btn btn-sm btn-ghost" @click="open(x)">编辑</button><button class="btn btn-sm btn-secondary" @click="derive(x)">以此新建</button><button class="btn btn-sm btn-ghost" @click="act(x,'expand')">AI扩写并生成提示词</button><button class="btn btn-sm btn-ghost" @click="act(x,'prompt')">重新编译提示词</button><button class="btn btn-sm btn-secondary" @click="act(x,'approve')">审核通过</button><button class="btn btn-sm" :disabled="x.audit_status!=='approved'&&x.audit_status!=='published'" @click="act(x,'image')">生成参考图</button><label class="btn btn-sm btn-ghost">上传图<input hidden type="file" accept="image/*" @change="upload(x,$event)"></label><button class="btn btn-sm btn-danger" @click="remove(x)">删除</button></div></article></div><div v-if="editing" class="modal-mask" @click.self="editing=null"><form class="modal card" @submit.prevent="save"><h2>{{form.id?'编辑':'新建'}}造型</h2><label>名称<input v-model="form.name" class="input" required></label><label>分类<select v-model="form.category" class="input"><option v-for="(v,k) in labels" :value="k">{{v}}</option></select></label><label>简单描述或详细描述<textarea v-model="form.description" class="textarea" rows="5" placeholder="例如：红色晚礼服，银色高跟鞋，适合宴会"></textarea></label><button type="button" class="btn btn-secondary" :disabled="expanding || !form.name || !form.description" @click="expandDraft">{{expanding?'AI扩写中…':'✨ AI扩写并生成提示词'}}</button><div class="field-hint">输入一句简单想法即可，AI 会结合角色外貌、项目题材和画风补全造型，并在下方生成 Krea2 提示词；确认后再保存。</div><label>参考图提示词<textarea v-model="form.prompt" class="textarea" rows="4"></textarea></label><label>优先级<input v-model.number="form.priority" type="number" min="0" max="100" class="input"></label><label><input v-model="form.is_shot_related" type="checkbox"> 镜头明确展示该造型时加入 H3 参考图</label><div class="actions"><button type="button" class="btn btn-ghost" @click="editing=null">取消</button><button class="btn">保存</button></div></form></div></div></template>
<script setup>import{onMounted,reactive,ref}from'vue';import{useRoute}from'vue-router';const r=useRoute(),pid=r.params.id,cid=r.params.cid,looks=ref([]),editing=ref(null),error=ref(''),expanding=ref(false);const labels={clothing:'服装',shoes:'鞋履',hair:'发型',hair_accessory:'发饰',jewelry:'首饰',bag:'包',full:'完整造型'};const form=reactive({});async function request(url,opt={}){const res=await fetch(url,opt);if(!res.ok)throw new Error((await res.json()).error||'请求失败');return res.status===204?null:res.json()}async function load(){try{looks.value=await request(`/api/projects/${pid}/characters/${cid}/looks`)}catch(e){error.value=e.message}}function open(x){Object.assign(form,x||{id:0,name:'',category:'clothing',description:'',prompt:'',priority:50,is_shot_related:false});editing.value=true}function derive(x){Object.assign(form,{id:0,name:x.name+'变体',category:x.category,description:x.description,prompt:x.prompt,priority:x.priority,is_shot_related:x.is_shot_related,is_default:false});editing.value=true}async function expandDraft(){expanding.value=true;error.value='';try{const data=await request(`/api/projects/${pid}/characters/${cid}/looks/expand-preview`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(form)});form.description=data.description;form.prompt=data.prompt}catch(e){error.value=e.message}finally{expanding.value=false}}async function save(){const url=`/api/projects/${pid}/characters/${cid}/looks${form.id?'/'+form.id:''}`;await request(url,{method:form.id?'PUT':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(form)});editing.value=null;load()}async function act(x,a){try{await request(`/api/projects/${pid}/characters/${cid}/looks/${x.id}/${a}`,{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});load()}catch(e){error.value=e.message}}async function upload(x,e){const f=e.target.files?.[0];if(!f)return;const fd=new FormData();fd.append('file',f);try{await request(`/api/projects/${pid}/characters/${cid}/looks/${x.id}/image/upload`,{method:'POST',body:fd});load()}catch(er){error.value=er.message}}async function remove(x){if(!confirm(`删除造型“${x.name}”？`))return;await request(`/api/projects/${pid}/characters/${cid}/looks/${x.id}`,{method:'DELETE'});load()}onMounted(load)</script>
<style scoped>.head{display:flex;justify-content:space-between;align-items:center;margin:16px 0}.look-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(310px,1fr));gap:16px}.look{padding:16px}.look img,.empty-img{width:100%;height:190px;object-fit:cover;border-radius:10px;background:var(--bg-secondary);display:grid;place-items:center;color:var(--text-tertiary)}header,.actions{display:flex;gap:8px;align-items:center;flex-wrap:wrap}header{justify-content:space-between}.modal{width:min(620px,92vw);display:grid;gap:14px;padding:22px}.modal label{display:grid;gap:6px}</style>